PRAGMA foreign_keys = ON;

UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"tall poised adult warrior-goddess with a strong spear-and-shield profile","appearance":{"face":["calm strategic gaze with disciplined adult features"],"body":["athletic adult proportions, elegant rather than bulky"]},"costumeLanguage":["bronze-and-ivory armor layered over Greek textile with a restrained crested helmet"],"paletteCues":["deep olive accents"],"temperament":["calm","strategic","authoritative"],"mythologicalFacts":["goddess of wisdom and strategic warfare"],"originalDesignChoices":["Keep ornament restrained so the Aegis and owl remain the strongest visual identifiers."],"avoid":["generic medieval fantasy costume","specific modern franchise likeness"],"canonicalPrompt":"Depict Athena as an original MythCanvas interpretation. Preserve spear, Aegis shield, owl motif; keep tall poised adult warrior-goddess with a strong spear-and-shield profile. Use bronze-and-ivory armor layered over Greek textile with a restrained crested helmet. Maintain a calm presence."}') WHERE id = 'character-athena';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"broad mature kingly figure framed by open sky and a raised thunderbolt","appearance":{"face":["mature bearded face with commanding but not villainous expression"],"body":["powerful mature adult build with upright regal posture"]},"costumeLanguage":["draped royal himation with restrained bronze-gold divine regalia"],"paletteCues":["storm white"],"temperament":["commanding","regal","volatile"],"mythologicalFacts":["king of the Olympian gods"],"originalDesignChoices":["Use weather and eagle motifs as secondary framing, never as random lightning clutter."],"avoid":["generic medieval fantasy costume","specific modern franchise likeness"],"canonicalPrompt":"Depict Zeus as an original MythCanvas interpretation. Preserve thunderbolt, eagle, royal sceptre; keep broad mature kingly figure framed by open sky and a raised thunderbolt. Use draped royal himation with restrained bronze-gold divine regalia. Maintain a commanding presence."}') WHERE id = 'character-zeus';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"powerful mature sea-god holding a long trident against a sweeping wave profile","appearance":{"face":["weathered mature face with intense seafarer authority"],"body":["strong adult build with grounded stance"]},"costumeLanguage":["sea-worn Greek drapery with bronze belt and minimal marine ornament"],"paletteCues":["sea green"],"temperament":["forceful","proud","elemental"],"mythologicalFacts":["god of the sea and earthquakes"],"originalDesignChoices":["Keep marine textures elegant and archaeological rather than turning him into a fish-armored fantasy king."],"avoid":["generic medieval fantasy costume","specific modern franchise likeness"],"canonicalPrompt":"Depict Poseidon as an original MythCanvas interpretation. Preserve trident, sea surge, horse motif; keep powerful mature sea-god holding a long trident against a sweeping wave profile. Use sea-worn Greek drapery with bronze belt and minimal marine ornament. Maintain a forceful presence."}') WHERE id = 'character-poseidon';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"reserved mature underworld king with vertical bident and heavy throne-like silhouette","appearance":{"face":["controlled mature face, stern and unreadable rather than monstrous"],"body":["tall adult build with still formal posture"]},"costumeLanguage":["dark Greek royal robes with subtle precious-metal details suggesting subterranean wealth"],"paletteCues":["charcoal purple"],"temperament":["reserved","stern","sovereign"],"mythologicalFacts":["ruler of the Greek underworld"],"originalDesignChoices":["Avoid skull-covered necromancer clichés; make him a divine king, not a generic demon."],"avoid":["generic medieval fantasy costume","specific modern franchise likeness"],"canonicalPrompt":"Depict Hades as an original MythCanvas interpretation. Preserve two-pronged bident, dark royal crown, Cerberus motif; keep reserved mature underworld king with vertical bident and heavy throne-like silhouette. Use dark Greek royal robes with subtle precious-metal details suggesting subterranean wealth. Maintain a reserved presence."}') WHERE id = 'character-hades';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"stately adult queen-goddess in a tall vertical draped silhouette","appearance":{"face":["mature elegant face with direct queenly gaze"],"body":["regal adult proportions with composed posture"]},"costumeLanguage":["formal peplos and mantle with a queenly diadem and restrained peacock-eye ornament"],"paletteCues":["peacock blue"],"temperament":["regal","watchful","unyielding"],"mythologicalFacts":["queen of Olympus and goddess of marriage"],"originalDesignChoices":["Use peacock iridescence only as accent, preserving a dignified classical queen rather than a feather costume."],"avoid":["generic medieval fantasy costume","specific modern franchise likeness"],"canonicalPrompt":"Depict Hera as an original MythCanvas interpretation. Preserve peacock, diadem, royal sceptre; keep stately adult queen-goddess in a tall vertical draped silhouette. Use formal peplos and mantle with a queenly diadem and restrained peacock-eye ornament. Maintain a regal presence."}') WHERE id = 'character-hera';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"graceful clearly adult goddess with flowing drapery and a soft shell-and-sea framing arc","appearance":{"face":["clearly adult refined face with serene self-possessed beauty"],"body":["graceful adult proportions, natural and non-exaggerated"]},"costumeLanguage":["elegant Greek drapery with layered translucent-over-opaque textile handled tastefully"],"paletteCues":["rose pearl"],"temperament":["serene","magnetic","self-possessed"],"mythologicalFacts":["goddess of love and beauty"],"originalDesignChoices":["Keep sensuality adult and dignified; avoid pin-up exaggeration or modern fashion styling."],"avoid":["specific modern franchise likeness","youth-coded sexualization"],"canonicalPrompt":"Depict Aphrodite as an original MythCanvas interpretation. Preserve sea foam, shell, dove; keep graceful clearly adult goddess with flowing drapery and a soft shell-and-sea framing arc. Use elegant Greek drapery with layered translucent-over-opaque textile handled tastefully. Maintain a serene presence."}') WHERE id = 'character-aphrodite';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"youthful-adult athletic god with clear lyre-or-bow profile and laurel crown","appearance":{"face":["clean youthful-adult face with focused luminous gaze"],"body":["lean athletic adult build"]},"costumeLanguage":["light Greek chiton and mantle with laurel and restrained gold sun accents"],"paletteCues":["sunlit gold"],"temperament":["luminous","composed","artistic"],"mythologicalFacts":["god associated with prophecy, music, archery and healing"],"originalDesignChoices":["Balance musician and archer cues without turning him into a generic sun-armored warrior."],"avoid":["generic medieval fantasy costume","specific modern franchise likeness"],"canonicalPrompt":"Depict Apollo as an original MythCanvas interpretation. Preserve lyre, laurel wreath, golden bow; keep youthful-adult athletic god with clear lyre-or-bow profile and laurel crown. Use light Greek chiton and mantle with laurel and restrained gold sun accents. Maintain a luminous presence."}') WHERE id = 'character-apollo';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"lean adult huntress-goddess with vertical bow and alert deer-like directional rhythm","appearance":{"face":["clearly adult focused face with alert gaze"],"body":["lean athletic adult build suited to movement"]},"costumeLanguage":["shorter practical Greek hunting chiton with mantle and simple leather gear"],"paletteCues":["moon silver"],"temperament":["independent","alert","reserved"],"mythologicalFacts":["goddess of the hunt and wilderness"],"originalDesignChoices":["Prioritize wilderness huntress identity; keep moon symbolism restrained and secondary."],"avoid":["generic medieval fantasy costume","specific modern franchise likeness"],"canonicalPrompt":"Depict Artemis as an original MythCanvas interpretation. Preserve bow, deer, crescent; keep lean adult huntress-goddess with vertical bow and alert deer-like directional rhythm. Use shorter practical Greek hunting chiton with mantle and simple leather gear. Maintain a independent presence."}') WHERE id = 'character-artemis';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"broad adult warrior-god with spear, shield and high helmet crest","appearance":{"face":["hard adult features with controlled battle intensity"],"body":["powerful athletic adult build"]},"costumeLanguage":["functional Greek bronze panoply with cloak, spear and round shield"],"paletteCues":["blood red"],"temperament":["aggressive","proud","restless"],"mythologicalFacts":["god of the violent and tumultuous aspect of war"],"originalDesignChoices":["Keep armor recognizably Greek and functional, avoiding oversized fantasy pauldrons."],"avoid":["generic medieval fantasy costume","specific modern franchise likeness"],"canonicalPrompt":"Depict Ares as an original MythCanvas interpretation. Preserve spear, war helmet, round shield; keep broad adult warrior-god with spear, shield and high helmet crest. Use functional Greek bronze panoply with cloak, spear and round shield. Maintain a aggressive presence."}') WHERE id = 'character-ares';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"lean youthful-adult messenger caught in a forward-moving diagonal with caduceus","appearance":{"face":["clever youthful-adult face with quick observant expression"],"body":["lean agile adult build"]},"costumeLanguage":["traveller''s cloak, petasos-inspired hat and light sandals with subtle wing symbolism"],"paletteCues":["warm tan"],"temperament":["quick","clever","playful"],"mythologicalFacts":["divine messenger and patron of travellers and trade"],"originalDesignChoices":["Treat wings as elegant symbolic accents rather than giant literal bird wings."],"avoid":["generic medieval fantasy costume","specific modern franchise likeness"],"canonicalPrompt":"Depict Hermes as an original MythCanvas interpretation. Preserve caduceus, winged travel motif, traveller''s hat; keep lean youthful-adult messenger caught in a forward-moving diagonal with caduceus. Use traveller''s cloak, petasos-inspired hat and light sandals with subtle wing symbolism. Maintain a quick presence."}') WHERE id = 'character-hermes';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"massive adult hero with lion skin creating a shoulder mantle and heavy club profile","appearance":{"face":["weathered determined adult face"],"body":["exceptionally muscular but anatomically grounded adult build"]},"costumeLanguage":["simple Greek tunic or heroic near-bare torso with the Nemean lion skin as the dominant garment"],"paletteCues":["lion tawny"],"temperament":["resolute","enduring","direct"],"mythologicalFacts":["hero famed for the Twelve Labours"],"originalDesignChoices":["Avoid bodybuilder-gloss aesthetics; retain a weathered mythic hero quality."],"avoid":["generic medieval fantasy costume","specific modern franchise likeness"],"canonicalPrompt":"Depict Heracles as an original MythCanvas interpretation. Preserve Nemean lion skin, wooden club, bow; keep massive adult hero with lion skin creating a shoulder mantle and heavy club profile. Use simple Greek tunic or heroic near-bare torso with the Nemean lion skin as the dominant garment. Maintain a resolute presence."}') WHERE id = 'character-heracles';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"clearly adult queen-goddess balancing an upright royal silhouette with delicate botanical arcs","appearance":{"face":["adult composed face with dual warmth and underworld gravity"],"body":["graceful adult proportions"]},"costumeLanguage":["layered Greek gown that transitions from spring floral embroidery to restrained underworld royal detail"],"paletteCues":["pomegranate red"],"temperament":["poised","dual-natured","quietly powerful"],"mythologicalFacts":["queen of the underworld and daughter of Demeter"],"originalDesignChoices":["Show spring/underworld duality through controlled material and light contrast, not split-face fantasy clichés."],"avoid":["generic medieval fantasy costume","specific modern franchise likeness"],"canonicalPrompt":"Depict Persephone as an original MythCanvas interpretation. Preserve pomegranate, grain, spring flowers; keep clearly adult queen-goddess balancing an upright royal silhouette with delicate botanical arcs. Use layered Greek gown that transitions from spring floral embroidery to restrained underworld royal detail. Maintain a poised presence."}') WHERE id = 'character-persephone';
